643→
644→        let base_yaml = r#"
645→app_name: BaseApp
646→steps:
647→  install:
648→    command: npm install
649→"#;
650→
651→        server.mock(|when, then| {
652→            when.method(GET).path("/base.yml");
653→            then.status(200).body(base_yaml);
654→        });
655→
656→        let temp = TempDir::new().unwrap();
657→        let bivvy_dir = temp.path().join(".bivvy");
658→        fs::create_dir_all(&bivvy_dir).unwrap();
659→
660→        // Project config extends base
661→        fs::write(
662→            bivvy_dir.join("config.yml"),
663→            format!(
664→                r#"
665→extends:
666→  - url: {}
667→app_name: ProjectApp
668→"#,
669→                server.url("/base.yml")
670→            ),
671→        )
672→        .unwrap();
673→
674→        // Local override file overrides app_name
675→        fs::write(
676→            bivvy_dir.join("config.local.yml"),
677→            "app_name: LocalOverride\n",
678→        )
