520→#[serde(untagged)]
521→pub enum VarDefinition {
522→    /// Computed from a shell command's stdout (trimmed).
523→    Computed {
524→        /// Shell command to run
525→        command: String,
526→    },
527→    /// A static string value.
528→    Static(String),
529→}
