602→/// `Some(val)` = set/override, `None` = remove the key from the base env.
603→#[derive(Debug, Clone, Default, Serialize, Deserialize)]
604→#[serde(default)]
605→pub struct StepEnvironmentOverride {
606→    /// Override step title
607→    #[serde(skip_serializing_if = "Option::is_none")]
608→    pub title: Option<String>,
609→
610→    /// Override step description
611→    #[serde(skip_serializing_if = "Option::is_none")]
612→    pub description: Option<String>,
613→
614→    /// Override step command
615→    #[serde(skip_serializing_if = "Option::is_none")]
616→    pub command: Option<String>,
617→
618→    /// Override/remove env vars (None value = remove key)
619→    #[serde(default, skip_serializing_if = "HashMap::is_empty")]
620→    pub env: HashMap<String, Option<String>>,
621→
622→    /// Override completed check
623→    #[serde(skip_serializing_if = "Option::is_none")]
624→    pub completed_check: Option<CompletedCheck>,
625→
626→    /// Override precondition
627→    #[serde(skip_serializing_if = "Option::is_none")]
628→    pub precondition: Option<CompletedCheck>,
629→
630→    /// Override skippable
631→    #[serde(skip_serializing_if = "Option::is_none")]
632→    pub skippable: Option<bool>,
633→
634→    /// Override allow_failure
635→    #[serde(skip_serializing_if = "Option::is_none")]
636→    pub allow_failure: Option<bool>,
637→
638→    /// Override requires_sudo
639→    #[serde(skip_serializing_if = "Option::is_none")]
640→    pub requires_sudo: Option<bool>,
641→
642→    /// Override sensitive
643→    #[serde(skip_serializing_if = "Option::is_none")]
644→    pub sensitive: Option<bool>,
645→
646→    /// Override before hooks
647→    #[serde(skip_serializing_if = "Option::is_none")]
648→    pub before: Option<Vec<String>>,
649→
650→    /// Override after hooks
651→    #[serde(skip_serializing_if = "Option::is_none")]
652→    pub after: Option<Vec<String>>,
653→
654→    /// Override dependencies
655→    #[serde(skip_serializing_if = "Option::is_none")]
656→    pub depends_on: Option<Vec<String>>,
657→
658→    /// Override requirements
659→    #[serde(skip_serializing_if = "Option::is_none")]
660→    pub requires: Option<Vec<String>>,
661→
662→    /// Override watches
663→    #[serde(skip_serializing_if = "Option::is_none")]
664→    pub watches: Option<Vec<String>>,
665→
666→    /// Override retry count
667→    #[serde(skip_serializing_if = "Option::is_none")]
668→    pub retry: Option<u32>,
669→}
