  1→//! Variable interpolation for configuration values.
  2→//!
  3→//! Bivvy supports variable interpolation in config values using `${variable}` syntax.
  4→//!
  5→//! # Syntax
  6→//!
  7→//! - `${variable_name}` - replaced with variable value
  8→//! - `$${escaped}` - produces literal `${escaped}` in output
  9→//!
 10→//! # Example
 11→//!
 12→//! ```yaml
 13→//! command: "echo Hello, ${name}!"
 14→//! # With name="World", produces: echo Hello, World!
 15→//! ```
 16→
 17→use crate::error::{BivvyError, Result};
 18→use std::collections::{HashMap, HashSet};
 19→
 20→/// A segment of an interpolated string.
 21→#[derive(Debug, Clone, PartialEq)]
 22→pub enum Segment {
 23→    /// Literal text
 24→    Literal(String),
 25→    /// Variable reference: ${name}
 26→    Variable(String),
 27→}
 28→
 29→/// Parse a string containing ${var} interpolations.
 30→///
 31→/// Supports:
 32→/// - `${variable_name}` - variable interpolation
 33→/// - `$${escaped}` - literal `${escaped}` in output
 34→///
 35→/// # Returns
 36→///
 37→/// Vec of segments representing the parsed string
 38→pub fn parse_interpolation(input: &str) -> Vec<Segment> {
 39→    let mut segments = Vec::new();
 40→    let mut chars = input.chars().peekable();
 41→    let mut current_literal = String::new();
 42→
 43→    while let Some(c) = chars.next() {
 44→        if c == '$' {
 45→            match chars.peek() {
 46→                Some('$') => {
 47→                    // Escaped: $$ becomes $
 48→                    chars.next();
 49→                    if chars.peek() == Some(&'{') {
 50→                        // $${...} -> literal ${...}
 51→                        chars.next(); // consume {
 52→                        current_literal.push('$');
 53→                        current_literal.push('{');
 54→                        // Read until closing brace
 55→                        while let Some(&c) = chars.peek() {
 56→                            chars.next();
 57→                            current_literal.push(c);
 58→                            if c == '}' {
 59→                                break;
 60→                            }
 61→                        }
 62→                    } else {
 63→                        current_literal.push('$');
 64→                    }
 65→                }
 66→                Some('{') => {
 67→                    // Start of variable
 68→                    chars.next(); // consume {
 69→
 70→                    // Flush current literal
 71→                    if !current_literal.is_empty() {
 72→                        segments.push(Segment::Literal(std::mem::take(&mut current_literal)));
 73→                    }
 74→
 75→                    // Read variable name until }
 76→                    let mut var_name = String::new();
 77→                    while let Some(&c) = chars.peek() {
 78→                        if c == '}' {
 79→                            chars.next();
 80→                            break;
 81→                        }
 82→                        var_name.push(chars.next().unwrap());
 83→                    }
 84→
 85→                    segments.push(Segment::Variable(var_name));
 86→                }
 87→                _ => {
 88→                    current_literal.push(c);
 89→                }
 90→            }
 91→        } else {
 92→            current_literal.push(c);
 93→        }
 94→    }
 95→
 96→    // Flush remaining literal
 97→    if !current_literal.is_empty() {
 98→        segments.push(Segment::Literal(current_literal));
 99→    }
100→
101→    segments
102→}
103→
104→/// Extract all variable names from an interpolated string.
105→///
106→/// Returns unique variable names found in the string.
107→pub fn extract_variables(input: &str) -> HashSet<String> {
108→    parse_interpolation(input)
109→        .into_iter()
110→        .filter_map(|seg| match seg {
111→            Segment::Variable(name) => Some(name),
112→            _ => None,
113→        })
114→        .collect()
115→}
116→
117→/// Check if a string contains any interpolation.
118→pub fn has_interpolation(input: &str) -> bool {
119→    parse_interpolation(input)
120→        .iter()
121→        .any(|seg| matches!(seg, Segment::Variable(_)))
122→}
123→
124→/// Context for variable resolution.
125→///
126→/// Variables are resolved in priority order:
127→/// 1. Prompt values from current run (highest priority)
128→/// 2. Saved preferences from previous runs
129→/// 3. User-defined variables from `vars:` config
130→/// 4. Environment variables
131→/// 5. Built-in variables (lowest priority)
132→#[derive(Debug, Default)]
133→pub struct InterpolationContext {
134→    /// Prompt values from current run
135→    pub prompts: HashMap<String, String>,
136→
137→    /// Saved preferences from previous runs
138→    pub preferences: HashMap<String, String>,
139→
140→    /// User-defined variables from `vars:` config
141→    pub vars: HashMap<String, String>,
142→
143→    /// Environment variables
144→    pub env: HashMap<String, String>,
145→
146→    /// Built-in variables (project_name, project_root, bivvy_version)
147→    pub builtins: HashMap<String, String>,
148→}
149→
150→impl InterpolationContext {
151→    /// Create a new context with built-in variables.
152→    pub fn new() -> Self {
153→        let mut builtins = HashMap::new();
154→        builtins.insert(
155→            "bivvy_version".to_string(),
156→            env!("CARGO_PKG_VERSION").to_string(),
157→        );
158→
159→        Self {
160→            builtins,
161→            ..Default::default()
162→        }
163→    }
164→
165→    /// Add project information to builtins.
166→    pub fn with_project(mut self, name: &str, root: &std::path::Path) -> Self {
167→        self.builtins
168→            .insert("project_name".to_string(), name.to_string());
169→        self.builtins
170→            .insert("project_root".to_string(), root.display().to_string());
171→        self
172→    }
173→
174→    /// Add user-defined variables.
175→    pub fn with_vars(mut self, vars: HashMap<String, String>) -> Self {
176→        self.vars = vars;
177→        self
178→    }
179→
180→    /// Add environment variables from a HashMap.
181→    pub fn with_env(mut self, env: HashMap<String, String>) -> Self {
182→        self.env = env;
183→        self
184→    }
185→
186→    /// Resolve a variable name to its value.
187→    ///
188→    /// Resolution order: prompts > preferences > vars > env > builtins
189→    pub fn resolve(&self, name: &str) -> Option<String> {
190→        self.prompts
191→            .get(name)
192→            .or_else(|| self.preferences.get(name))
193→            .or_else(|| self.vars.get(name))
194→            .or_else(|| self.env.get(name))
195→            .or_else(|| self.builtins.get(name))
196→            .cloned()
197→    }
198→}
199→
200→/// Resolve all variables in an interpolated string.
201→///
202→/// # Errors
203→///
204→/// Returns `ConfigValidationError` if any variable is not found in the context.
205→pub fn resolve_string(input: &str, context: &InterpolationContext) -> Result<String> {
206→    let segments = parse_interpolation(input);
207→    let mut result = String::new();
208→
209→    for segment in segments {
210→        match segment {
211→            Segment::Literal(text) => result.push_str(&text),
212→            Segment::Variable(name) => {
213→                let value =
214→                    context
215→                        .resolve(&name)
216→                        .ok_or_else(|| BivvyError::ConfigValidationError {
217→                            message: format!("Unresolved variable: ${{{}}}", name),
218→                        })?;
219→                result.push_str(&value);
220→            }
221→        }
222→    }
223→
224→    Ok(result)
225→}
226→
227→/// Resolve string with optional default value for missing variables.
228→///
229→/// Unlike `resolve_string`, this never fails - missing variables
230→/// are replaced with the provided default.
231→pub fn resolve_string_with_default(
232→    input: &str,
233→    context: &InterpolationContext,
234→    default: &str,
235→) -> String {
236→    let segments = parse_interpolation(input);
237→    let mut result = String::new();
238→
239→    for segment in segments {
240→        match segment {
241→            Segment::Literal(text) => result.push_str(&text),
242→            Segment::Variable(name) => {
243→                let value = context
244→                    .resolve(&name)
245→                    .unwrap_or_else(|| default.to_string());
246→                result.push_str(&value);
247→            }
248→        }
249→    }
250→
251→    result
252→}
